// Extract PR details and commit diff
const body = $json.body || {};
const pr = body.pull_request || {};
const repo = body.repository || {};

const title = pr.title || 'Manual Security Scan';
const prNumber = pr.number || 1;
const repoFullName = repo.full_name || 'CodeRaksh/Internal';
const diffUrl = pr.diff_url || '';
const sender = body.sender?.login || 'developer';
const branch = pr.head?.ref || 'main';

// Extract PR body / description / changed files
const description = pr.body || 'No description provided';
const patchSnippet = body.comment?.body || body.diff || description;

return [{
  json: {
    pr_number: prNumber,
    pr_title: title,
    repo_name: repoFullName,
    branch: branch,
    author: sender,
    diff_url: diffUrl,
    code_diff_snippet: patchSnippet,
    timestamp: $now.toFormat('dd LLL yyyy, HH:mm')
  }
}];

// Pre-scan for leaked secrets and high-risk patterns
const diff = String($json.code_diff_snippet || '');
const leaks = [];

if (/[A-Za-z0-9_-]{20,40}/.test(diff) && (diff.includes('sk-ant-') || diff.includes('sk-') || diff.includes('AIzaSy'))) {
  leaks.push('Potential AI API Key (Anthropic / OpenAI / Google)');
}
if (/AKIA[0-9A-Z]{16}/.test(diff)) {
  leaks.push('AWS Access Key ID');
}
if (/ghp_[0-9a-zA-Z]{36}/.test(diff) || /github_pat_[0-9a-zA-Z_]{82}/.test(diff)) {
  leaks.push('GitHub Personal Access Token');
}
if (/-----BEGIN (RSA |EC )?PRIVATE KEY-----/.test(diff)) {
  leaks.push('Private SSH/TLS Key');
}
if (/postgres:\/\/|mongodb(\+srv)?:\/\/|mysql:\/\//.test(diff)) {
  leaks.push('Database Connection String with Credentials');
}

return [{
  json: {
    ...$json,
    secret_leaks_found: leaks,
    has_hardcoded_secrets: leaks.length > 0
  }
}];

// Check if audit requires immediate founder escalation
const text = $('Claude DevSecOps Auditor').first().json.text || '';
const hasLeaks = $('Fast Secret & Leak Scanner').first().json.has_hardcoded_secrets;
const isCritical = text.includes('CRITICAL_BLOCK') || text.includes('CRITICAL') || text.includes('HIGH') || hasLeaks;

return [{
  json: {
    is_critical: isCritical,
    alert_message: `🚨 *[CODERAKSH DEVSECOPS ALERT]*\nRepo: ${$('Extract PR & Code Context').first().json.repo_name}\nPR #${$('Extract PR & Code Context').first().json.pr_number}: ${$('Extract PR & Code Context').first().json.pr_title}\nAuthor: ${$('Extract PR & Code Context').first().json.author}\nRisk: CRITICAL SECURITY FINDINGS OR LEAKS DETECTED!\nReview posted to GitHub.`
  }
}];
